import{_ as i,a0 as l,w as o,s as d,ao as r,I as p,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"用 bash 倒計時日期 | LCTT x X-CMD","titleTemplate":false,"description":"用 bash 倒計時日期 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 bash 倒計時日期 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 bash 倒計時日期 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191209 Counting down the days using bash","title":"用 bash 倒計時日期","tag":"201912","desc":""},"relativePath":"201912/20191209 Counting down the days using bash.md","filePath":"[post].md"}'),h={name:"201912/20191209 Counting down the days using bash.md"};function u(c,s,g,b,k,m){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="用-bash-倒計時日期" tabindex="-1">用 bash 倒計時日期 <a class="header-anchor" href="#用-bash-倒計時日期" aria-label="Permalink to “用 bash 倒計時日期”">​</a></h1><blockquote><p>需要知道重要事件發生前有多少天嗎？讓 Linux bash 和 date 命令可以幫助你！</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201912/13/140725vdc3c7zj0o7ozc7j.jpg" alt=""></p><p>隨着即將來臨的重要假期，你可能需要提醒你還要準備多久。</p><p>幸運的是，你可以從 <code>date</code> 命令獲得很多幫助。在本篇中，我們將研究 <code>date</code> 和 bash 腳本如何告訴你從今天到你預期的事件之間有多少天。</p><p>首先，在進行之前有幾個提示。<code>date</code> 命令的 <code>%j</code> 選項將以 1 至 366 之間的數字顯示當前日期。如你所想的一樣，1 月 1 日將顯示為 1，12 月 31 日將顯示為 365 或 366，這取決於是否是閏年。繼續嘗試。你應該會看到以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date +%j</span></span>
<span class="line"><span>339</span></span></code></pre></div><p>但是，你可以通過以下方式，在 <code>date</code> 命令中得到一年中<em>任何</em>一天的數字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date -d &quot;Mar 18&quot; +%j</span></span>
<span class="line"><span>077</span></span></code></pre></div><p>要記住的是，即使該日期是過去的日期，上面命令也會向你顯示<em>當年</em>的日期。但是，你可以在命令中添加年來修復該問題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date -d &quot;Apr 29&quot; +%j</span></span>
<span class="line"><span>119</span></span>
<span class="line"><span>$ date -d &quot;Apr 29 2020&quot; +%j</span></span>
<span class="line"><span>120</span></span></code></pre></div><p>在閏年中，4 月 29 日將是一年的 120 天，而不是 119 天。</p><p>如果你想倒數聖誕節之前的日子並且不想在掛曆上留下指紋，你可以使用以下腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>XMAS=\`date -d &quot;Dec 25&quot; +%j\`</span></span>
<span class="line"><span>TODAY=\`date +%j\`</span></span>
<span class="line"><span>DAYS=$(($XMAS - $TODAY))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>case $DAYS in</span></span>
<span class="line"><span>  0) echo &quot;It&#39;s today! Merry Christmas!&quot;;;</span></span>
<span class="line"><span>  [0-9]*) echo &quot;$DAYS days remaining&quot;;;</span></span>
<span class="line"><span>  -[0-9]*) echo &quot;Oops, you missed it&quot;;;</span></span>
<span class="line"><span>esac</span></span></code></pre></div><p>在此腳本中，我們獲取 12 月 25 日和今天的日期，然後相減。如果結果是正數，我們將顯示剩餘天數。如果為零，則發出 “Merry Christmas” 的消息，如果為負，那麼僅告訴運行腳本的人他們錯過了假期。也許他們沉迷在蛋酒中了。</p><p><code>case</code> 語句由用來打印信息的語句組成，當剩餘時間等於 0，或任意數字或以 <code>-</code> 符號開頭的數字（也就是過去）分別打印不同的信息。</p><p>對於人們想要關注的任何日期，都可以使用相同方法。實際上，我們可以要求運行腳本的人員提供日期，然後讓他們知道從現在到那天還有多少天。這個腳本是這樣的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo -n &quot;Enter event date (e.g., June 6): &quot;</span></span>
<span class="line"><span>read dt</span></span>
<span class="line"><span>EVENT=\`date -d &quot;$dt&quot; +%j\`</span></span>
<span class="line"><span>TODAY=\`date +%j\`</span></span>
<span class="line"><span>DAYS=\`expr $EVENT - $TODAY\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>case $DAYS in</span></span>
<span class="line"><span>  0) echo &quot;It&#39;s today!&quot;;;</span></span>
<span class="line"><span>  [0-9]*) echo &quot;$DAYS days remaining&quot;;;</span></span>
<span class="line"><span>  -[0-9]*) echo &quot;Oops, you missed it&quot;;;</span></span>
<span class="line"><span>esac</span></span></code></pre></div><p>使用此腳本會遇到的一個問題，如果運行該腳本的人希望知道到第二年這個特殊日子還有多少天，他們會感到失望。即使他們輸入日期時提供了年，<code>date -d</code> 命令仍將僅提供今年中的天數，而不會提供從現在到那時的天數。</p><p>計算從今天到某年的日期之間的天數可能有些棘手。你需要包括所有中間年份，並注意那些閏年。</p><h3 id="使用-unix-紀元時間" tabindex="-1">使用 Unix 紀元時間 <a class="header-anchor" href="#使用-unix-紀元時間" aria-label="Permalink to “使用 Unix 紀元時間”">​</a></h3><p>計算從現在到某個特殊日期之間的天數的另一種方法是利用 Unix 系統存儲日期的方法。如果將自 1970 年 1 月 1 日開始的秒數轉換為天數，那麼就可以很容易地執行此操作，如下腳本所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo -n &quot;Enter target date (e.g., Mar 18 2021)&gt; &quot;</span></span>
<span class="line"><span>read target_date</span></span>
<span class="line"><span>today=\`echo $(($(date --utc --date &quot;$1&quot; +%s)/86400))\`</span></span>
<span class="line"><span>target=\`echo $(($(date --utc --date &quot;$target_date&quot; +%s)/86400))\`</span></span>
<span class="line"><span>days=\`expr $target - $today\`</span></span>
<span class="line"><span>echo &quot;$days days until $target_date&quot;</span></span></code></pre></div><p>解釋一下，86400 是一天中的秒數。將自 Unix 紀元開始以來的秒數除該數即為天數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./countdown</span></span>
<span class="line"><span>Enter target date (e.g., Mar 18 2021)&gt; Mar 18 2020</span></span>
<span class="line"><span>104 days until Mar 18 2020</span></span></code></pre></div><hr>`,26)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3487712/counting-down-the-days-using-bash.html"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3487712/counting-down-the-days-using-bash.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const q=i(h,[["render",u]]);export{C as __pageData,q as default};
